mapper.insert:
INSERT INTO kb_document_object_cleanup (
    tenant_id, knowledge_base_id, document_id, bucket, object_key, source_uri,
    observation_failure_type, status, attempt_count, next_attempt_at,
    observed_at, created_at, updated_at
) VALUES (
    #{tenantId}, #{knowledgeBaseId}, #{documentId}, #{bucket}, #{objectKey}, #{sourceUri},
    #{failureType}, 'PENDING', 0, #{firstAttemptAt}, #{observedAt}, #{observedAt}, #{observedAt}
)
ON CONFLICT (tenant_id, bucket, object_key) DO NOTHING

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM kb_document document
    WHERE document.tenant_id = cleanup.tenant_id
      AND document.knowledge_base_id = cleanup.knowledge_base_id
      AND document.id = cleanup.document_id
      AND document.source_uri = cleanup.source_uri
      AND document.deleted_at IS NULL
)
FROM kb_document_object_cleanup cleanup
WHERE cleanup.tenant_id = #{tenantId}
  AND cleanup.id = #{cleanupId}
  AND cleanup.status = 'PROCESSING'
  AND cleanup.lease_owner = #{leaseOwner}
  AND cleanup.lease_token = #{leaseToken}
  AND cleanup.version = #{fenceVersion}
  AND cleanup.lease_until > #{now}

mapper.update:
UPDATE kb_document_object_cleanup
SET status = 'COMPLETED', next_attempt_at = NULL,
    lease_owner = NULL, lease_token = NULL, lease_until = NULL,
    failure_code = NULL, failure_reason = NULL,
    completed_at = #{now}, updated_at = #{now}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{cleanupId}
  AND status = 'PROCESSING'
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}

UPDATE kb_document_object_cleanup
SET status = 'RETAINED', next_attempt_at = NULL,
    lease_owner = NULL, lease_token = NULL, lease_until = NULL,
    failure_code = NULL, failure_reason = NULL,
    completed_at = #{now}, updated_at = #{now}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{cleanupId}
  AND status = 'PROCESSING'
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}

UPDATE kb_document_object_cleanup
SET status = 'RETRY_WAIT', next_attempt_at = #{nextRetryAt},
    lease_owner = NULL, lease_token = NULL, lease_until = NULL,
    failure_code = #{failureCode}, failure_reason = #{failureSummary},
    completed_at = NULL, updated_at = #{now}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{cleanupId}
  AND status = 'PROCESSING'
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}

UPDATE kb_document_object_cleanup
SET status = 'FAILED', next_attempt_at = NULL,
    lease_owner = NULL, lease_token = NULL, lease_until = NULL,
    failure_code = #{failureCode}, failure_reason = #{failureSummary},
    completed_at = #{now}, updated_at = #{now}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{cleanupId}
  AND status = 'PROCESSING'
  AND lease_owner = #{leaseOwner}
  AND lease_token = #{leaseToken}
  AND version = #{fenceVersion}
  AND lease_until > #{now}
